return {["fb203_01"]={["dsc"]=[[这是一个小木屋，门边写着“陶然”二字，屋子全部由紫竹搭建而成，散发着奇异的清香。门前还有一柄巨大的斧头。]],["id"]=[[fb203_01]],["name"]=[[陶然屋]],["permission"]=1,["role1"]=[[fb203r01_1]],["role2"]=[[fb203item51]],["role3"]=[[fb203item19]],["role4"]=[[fb203item37]],["stepMusic"]=[[jiaobu]],["up"]=[[fb203_02]]},["fb203_02"]={["down"]=[[fb203_01]],["dsc"]=[[这是天河边的一条小路。小路由晶莹剔透的碎石铺就，踩上去发出轻微的摩擦声。小路旁不时传来天河拍的河岸的涛声。前面似乎是一所木屋。]],["id"]=[[fb203_02]],["name"]=[[听涛路]],["permission"]=1,["right"]=[[fb203_03]],["role1"]=[[fb203item19]],["role2"]=[[fb203item27]],["stepMusic"]=[[jiaobu]]},["fb203_03"]={["dsc"]=[[这里便是天河的河岸边。天河中波光粼粼，走在河边，看着浩大的天河川流不息，一时间流光四溢，美不胜收。]],["id"]=[[fb203_03]],["left"]=[[fb203_02]],["name"]=[[天河岸]],["permission"]=1,["role1"]=[[fb203item19]],["role2"]=[[fb203item25]],["stepMusic"]=[[jiaobu]],["up"]=[[fb203_06]]},["fb203_04"]={["dsc"]=[[这里便是天河的河岸边。天河中波光粼粼，走在河边，看着浩大的天河川流不息，一时间流光四溢，美不胜收。]],["id"]=[[fb203_04]],["name"]=[[天河岸]],["permission"]=1,["right"]=[[fb203_05]],["role1"]=[[fb203item50]],["role2"]=[[fb203item19]],["role3"]=[[fb203item31]],["role4"]=[[fb203r04_1]],["stepMusic"]=[[jiaobu]]},["fb203_05"]={["dsc"]=[[这里便是天河的河岸边。天河中波光粼粼，走在河边，看着浩大的天河川流不息，一时间流光四溢，美不胜收。]],["id"]=[[fb203_05]],["left"]=[[fb203_04]],["name"]=[[天河岸]],["permission"]=1,["role1"]=[[fb203r05_1]],["role2"]=[[fb203item45]],["role3"]=[[fb203item19]],["role4"]=[[fb203item32]],["stepMusic"]=[[jiaobu]],["up"]=[[fb203_07]]},["fb203_06"]={["down"]=[[fb203_03]],["dsc"]=[[这里是一片茂密的果林。走进林子，薄雾缭绕，风景如梦似幻。果林中长着许多不知名的果子，都散发着粼粼金光。前方似乎就是林子的尽头了。]],["id"]=[[fb203_06]],["item1"]=[[fb203item24]],["item2"]=[[fb203item19]],["item3"]=[[fb203item36]],["name"]=[[金果林]],["permission"]=1,["role1"]=[[fb203item20]],["role2"]=[[fb203item21]],["role3"]=[[fb203item22]],["role4"]=[[fb203item23]],["stepMusic"]=[[jiaobu]],["up"]=[[fb203_08]]},["fb203_07"]={["down"]=[[fb203_05]],["dsc"]=[[离开天河河岸，走上了一条由白玉铸成的小路。这条路源自金风玉露相逢之时的典故，走在这条白玉路上，你的心情似乎也好了不少。]],["id"]=[[fb203_07]],["name"]=[[金玉路]],["permission"]=1,["role1"]=[[fb203item19]],["stepMusic"]=[[jiaobu]],["up"]=[[fb203_09]]},["fb203_08"]={["down"]=[[fb203_06]],["dsc"]=[[这里是一片茂密的果林。走进林子，薄雾缭绕，风景如梦似幻。果林中长着许多不知名的果子，都散发着粼粼金光。前方似乎就是林子的尽头了。]],["id"]=[[fb203_08]],["item1"]=[[fb203item15]],["item2"]=[[fb203item17]],["item3"]=[[fb203item56]],["item4"]=[[fb203item19]],["name"]=[[金果林]],["permission"]=1,["role1"]=[[fb203item7]],["role2"]=[[fb203item9]],["role3"]=[[fb203item11]],["role4"]=[[fb203item13]],["stepMusic"]=[[jiaobu]],["up"]=[[fb203_11]]},["fb203_09"]={["down"]=[[fb203_07]],["dsc"]=[[离开天河河岸，走上了一条由白玉铸成的小路。这条路源自金风玉露相逢之时的典故，走在这条白玉路上，你的心情似乎也好了不少。]],["id"]=[[fb203_09]],["name"]=[[金玉路]],["permission"]=1,["role1"]=[[fb203item19]],["role2"]=[[fb203item34]],["stepMusic"]=[[jiaobu]],["up"]=[[fb203_14]]},["fb203_10"]={["dsc"]=[[这里便是天河的河岸边。天河中波光粼粼，走在河边，看着浩大的天河川流不息，一时间流光四溢，美不胜收。]],["id"]=[[fb203_10]],["leftUp"]=[[fb203_15]],["name"]=[[天河岸]],["permission"]=1,["right"]=[[fb203_11]],["role1"]=[[fb203item45]],["role2"]=[[fb203item5]],["role3"]=[[fb203item19]],["stepMusic"]=[[jiaobu]]},["fb203_11"]={["down"]=[[fb203_08]],["dsc"]=[[这里是似乎是一座桥的一端，桥旁树立着一块发出七彩光芒的灵石，上书“望归”二字。桥杆居然由金玉打造的，不过桥身似乎被损坏了，一位英俊的年轻人正左右踱步，似乎十分焦急。]],["id"]=[[fb203_11]],["left"]=[[fb203_10]],["name"]=[[望归石]],["permission"]=1,["role1"]=[[fb203r11_1]],["role2"]=[[fb203item55]],["role3"]=[[fb203item19]],["role4"]=[[fb203item43]],["stepMusic"]=[[jiaobu]]},["fb203_12"]={["dsc"]=[[浩大的天河在脚下翻滚着，咆哮着，似乎正在诉说着什么，鹊桥竟真的是由飞翔的喜鹊编制而成，桥上有一对年轻的男女正拥抱在一起。]],["id"]=[[fb203_12]],["name"]=[[鹊桥]],["permission"]=1,["role1"]=[[fb203r12_1]],["role2"]=[[fb203r12_2]],["stepMusic"]=[[jiaobu]]},["fb203_13"]={["dsc"]=[[这里是似乎是一座桥的一端，桥旁树立着一块发出七彩光芒的灵石，上书“祈归”二字。一位美丽的仙女正含情脉脉地望着对岸。]],["id"]=[[fb203_13]],["name"]=[[祈归石]],["permission"]=1,["right"]=[[fb203_14]],["role1"]=[[fb203r13_1]],["role2"]=[[fb203item19]],["stepMusic"]=[[jiaobu]]},["fb203_14"]={["down"]=[[fb203_09]],["dsc"]=[[这里便是天河的河岸边。天河中波光粼粼，走在河边，看着浩大的天河川流不息，一时间流光四溢，美不胜收。]],["id"]=[[fb203_14]],["left"]=[[fb203_13]],["name"]=[[天河岸]],["permission"]=1,["role1"]=[[fb203item45]],["role2"]=[[fb203item52]],["role3"]=[[fb203item19]],["role4"]=[[fb203item33]],["stepMusic"]=[[jiaobu]]},["fb203_15"]={["dsc"]=[[这里便是天河的河岸边。天河中波光粼粼，走在河边，看着浩大的天河川流不息，一时间流光四溢，美不胜收。再往前便是天河尽头了。]],["id"]=[[fb203_15]],["leftUp"]=[[fb203_16]],["name"]=[[天河岸]],["permission"]=1,["rightDown"]=[[fb203_10]],["role1"]=[[fb203item45]],["role2"]=[[fb203item1]],["role3"]=[[fb203item19]],["stepMusic"]=[[jiaobu]]},["fb203_16"]={["dsc"]=[[这里是天河的极北之地，也是天河的源头。站在源头的岸边，只见天空中云卷云舒，一道金光射下，云层破开一个窟窿。天河便倾倒而下，飞瀑环流，美不胜收。]],["id"]=[[fb203_16]],["name"]=[[天涯海角]],["permission"]=1,["rightDown"]=[[fb203_15]],["role1"]=[[fb203item19]],["role2"]=[[fb203item44]],["stepMusic"]=[[jiaobu]]},["fb203_17"]={["dsc"]=[[放眼四周全是茫茫的白云，你的下方似有一片实地。]],["id"]=[[fb203_17]],["name"]=[[飞仙台]],["permission"]=1,["role1"]=[[fb203item3]],["role2"]=[[fb203item19]],["stepMusic"]=[[jiaobu]]}}000000